#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> a(n), b(m);
    for (int &x : a) cin >> x;

    long long patternLength = 0;
    for (int &x : b) {
        cin >> x;
        patternLength += x;
    }

    if (patternLength == 0) {
        cout << "YES";
        return 0;
    }

    if (patternLength > n) {
        cout << "NO";
        return 0;
    }

    vector<int> pattern;
    pattern.reserve(static_cast<size_t>(patternLength));

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < b[i]; ++j) {
            pattern.push_back(i + 1);
        }
    }

    vector<int> prefix(pattern.size());
    for (size_t i = 1, j = 0; i < pattern.size(); ++i) {
        while (j > 0 && pattern[i] != pattern[j]) {
            j = prefix[j - 1];
        }
        if (pattern[i] == pattern[j]) ++j;
        prefix[i] = static_cast<int>(j);
    }

    size_t matched = 0;
    for (int x : a) {
        while (matched > 0 && x != pattern[matched]) {
            matched = prefix[matched - 1];
        }
        if (x == pattern[matched]) ++matched;

        if (matched == pattern.size()) {
            cout << "YES";
            return 0;
        }
    }

    cout << "NO";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> a(n);
    for (int& x : a) cin >> x;

    vector<int> b(m + 1);
    long long total = 0;

    for (int i = 1; i <= m; ++i) {
        cin >> b[i];
        total += b[i];
    }

    if (total == 0) {
        cout << "YES";
        return 0;
    }

    if (total > n) {
        cout << "NO";
        return 0;
    }

    vector<int> pattern;
    pattern.reserve(static_cast<size_t>(total));

    for (int i = 1; i <= m; ++i) {
        pattern.insert(pattern.end(), b[i], i);
    }

    vector<int> prefix(pattern.size());

    for (size_t i = 1, j = 0; i < pattern.size(); ++i) {
        while (j > 0 && pattern[i] != pattern[j]) {
            j = prefix[j - 1];
        }
        if (pattern[i] == pattern[j]) {
            ++j;
        }
        prefix[i] = static_cast<int>(j);
    }

    size_t matched = 0;

    for (int value : a) {
        while (matched > 0 && value != pattern[matched]) {
            matched = prefix[matched - 1];
        }

        if (value == pattern[matched]) {
            ++matched;
        }

        if (matched == pattern.size()) {
            cout << "YES";
            return 0;
        }
    }

    cout << "NO";
    return 0;
}

